package name.milesparker.epi.region;

/**
 * Region Java Implementation.
 * 
 * Generated by metaabm system: Dec 11, 2009 6:59:51 PM PST in project: org.eclipse.amp.amf.examples.escape  */
public class Region3D extends Region
		implements
			org.eclipse.amp.agf3d.I3DModelFactoryProvider {
	public void createGraphicViews() {
		addView(new org.eclipse.amp.escape.ascape.agf3d.GEF3DView());
	}

	public org.eclipse.gef.EditPartFactory getEditPart3DFactory() {
		return new org.eclipse.amp.escape.ascape.adapt.Ascape3DPartFactory() {
			public org.eclipse.jface.viewers.IColorProvider getColorProvider(
					Object model) {

				if (model instanceof City) {
					return new name.milesparker.epi.region.CityStyle2DColorProvider();
				}

				if (model instanceof Individual) {
					return new name.milesparker.epi.region.IndividualStyle2DColorProvider();
				}

				return null;
			}
		};
	}

}
